import { ComponentFixture, TestBed } from '@angular/core/testing';

import { LoginComponent } from './login.component';
import { AuthService } from '../../services/auth.service';
import { Router } from '@angular/router';
import { of } from 'rxjs';

class MockAuthService {
  login(email: string, password: string) {
    return of({ token: 'test-jwt-token' });
  }
  logout() {
    localStorage.removeItem('authToken');
  }
}

describe('LoginComponent', () => {
  let component: LoginComponent;
  let fixture: ComponentFixture<LoginComponent>;
  let authService: AuthService;
  let routerSpy = jasmine.createSpyObj('Router', ['navigate']);

  beforeEach(async () => {
    await TestBed.configureTestingModule({
      declarations: [LoginComponent],
      providers: [
        { provide: AuthService, useClass: MockAuthService },
        { provide: Router, useValue: routerSpy }
      ]
    }).compileComponents();

    fixture = TestBed.createComponent(LoginComponent);
    component = fixture.componentInstance;
    authService = TestBed.inject(AuthService);
  });

  it('should log in a user and navigate to /products', () => {
    spyOn(authService, 'login').and.callThrough();
    component.email = 'test@example.com';
    component.password = 'password123';

    component.login();
    expect(authService.login).toHaveBeenCalledWith('test@example.com', 'password123');
    expect(localStorage.getItem('authToken')).toBe('test-jwt-token');
    expect(routerSpy.navigate).toHaveBeenCalledWith(['/products']);
  });

  it('should log out a user and navigate to /login', () => {
    spyOn(authService, 'logout').and.callThrough();

    component.logout(); // Assume there is a logout method in the component
    expect(authService.logout).toHaveBeenCalled();
    expect(localStorage.getItem('authToken')).toBeNull();
    expect(routerSpy.navigate).toHaveBeenCalledWith(['/login']);
  });
});
